const SUCHINDRAM_INFO={id:"suchindram-wetland",name:"Suchindram Theroor Wetland Complex",localName:"Suchindram Kulam Bird Sanctuary (சுசீந்திரம் பறவைகள் சரணாலயம்)",location:"Suchindram, Kanyakumari District, Tamil Nadu, India",state:"Tamil Nadu",coordinates:{lat:8.1502,lng:77.4658},area:"94.23 hectares (0.94 km²)",establishedYear:2002,ramsarYear:2022,ramsarSiteNo:2484,wetlandType:"Freshwater Irrigation Tank & Marshland Complex",riverBasin:"Pazhayar River Basin",climate:"Tropical Coastal Maritime",bestTime:"October to March (Peak Migratory Nesting Season)",nearestTransport:{town:"Nagercoil (7 km) / Kanyakumari (12 km)",airport:"Tiruvananthapuram International Airport (TRV - 75 km)",railway:"Nagercoil Junction (7 km) / Kanyakumari Railway Station (12 km)"},quickStats:[{label:"Ramsar Site Designated",value:"2022 (No. 2484)",icon:"💧"},{label:"Wetland Complex Area",value:"94.23 Hectares",icon:"🌾"},{label:"Avian Species",value:"150+ Species",icon:"🦅"},{label:"Southernmost Flyway",value:"CAF Tip Haven",icon:"📍"},{label:"Wintering Migrants",value:"15,000+ Waterfowl",icon:"🦩"},{label:"IBA Status",value:"Code IN-TN-28",icon:"🏛️"}]},SUCHINDRAM_SECTIONS={history:{title:"History & Heritage",subtitle:"Centuries of traditional water harvest serving as the southern jewel of Kanyakumari's tanks.",paragraphs:["Suchindram Wetland has a rich agrarian history dating back to the reign of the Venad and Travancore kingdoms. Constructed over several centuries to store monsoon floodwaters from the Pazhayar River, the tank was designed to irrigate paddy fields surrounding the sacred Suchindram Thanumalayaswamy Temple.","Recognizing its critical role as a terminus for wintering migratory waterfowl along the Central Asian Flyway, the Government of Tamil Nadu notified the Suchindram-Theroor tank complex as a protected Conservation Reserve and Bird Sanctuary in 2002. In August 2022, UNESCO Ramsar Convention officially designated the Suchindram Theroor Wetland Complex as Ramsar Site No. 2484."]},ramsarSite:{title:"Ramsar Site Designation",subtitle:"Internationally Recognized Wetland of Importance (Site No. 2484)",paragraphs:["On August 3, 2022, Suchindram Theroor Wetland Complex was formally declared Ramsar Site No. 2484, spanning 94.23 hectares. The designation highlights its crucial ecological role in preserving freshwater biodiversity near mainland India's southernmost point.","As the southern terminus of the Central Asian Flyway (CAF) in India, Suchindram serves as a vital staging ground where migratory birds rest and refuel before either overwintering in Tamil Nadu's coastal zone or making the oceanic crossing to Sri Lanka."]},freshwaterWetland:{title:"Freshwater Wetland Ecosystem",subtitle:"A human-modified freshwater lake fed by Pazhayar River runoff and monsoon rains.",paragraphs:["Suchindram is a perennial-to-seasonal freshwater irrigation wetland complex comprising shallow open water, floating macrophyte beds, and mudflats. High rainfall during both the South-West and North-East monsoons replenishes the tank, sustaining extensive lotus (Nelumbo nucifera) and water lily beds.","Submerged tree islands planted with Acacia nilotica and Barringtonia acutangula provide safe elevated nesting platforms insulated by surrounding water, attracting breeding colonies of storks, pelicans, and egrets."]},aquaticBiodiversity:{title:"Aquatic Biodiversity",subtitle:"Rich aquatic vegetation and indigenous fish supporting a complex web of life.",paragraphs:["The wetland supports diverse macrophyte species including Hydrilla verticillata, Utricularia, and Vallisneria, which supply oxygen and cover for freshwater fauna. Dense floating mats of lily pads provide ideal habitat for wading birds like Bronze-winged and Pheasant-tailed Jacanas.","Fish species such as Snakehead (Channa striata), Climbing Perch (Anabas testudineus), Catfish (Clarias batrachus), and indigenous Puntius barbs thrive in the tank, sustaining large populations of diving piscivorous birds like Darters, Pelicans, and Cormorants."]},conservation:{title:"Conservation & Protection",subtitle:"Forest Department management and community stewardship near temple lands.",paragraphs:["Suchindram Wetland is managed by the Tamil Nadu Forest Department (Kanyakumari Division). Key management initiatives include de-silting feeder channels, monitoring agricultural runoff, eradicating invasive Water Hyacinth, and maintaining perimeter bund eco-trails.","Local temple authorities and nearby residents actively support bird conservation, refraining from noisy festivities during nesting months and protecting roosting trees from disturbance."]}},INTERESTING_FACTS=[{title:"Southernmost Flyway Staging Post",icon:"📍",fact:"Suchindram is the southernmost major freshwater bird sanctuary on mainland India, serving as the final staging post along the Central Asian Flyway."},{title:"Jacana Sanctuary",icon:"🪶",fact:"The extensive lotus and water lily mats of Suchindram tank support one of Southern Tamil Nadu's dense breeding populations of Bronze-winged and Pheasant-tailed Jacanas."},{title:"Sacred Temple Pond Synergy",icon:"🛕",fact:"Located right next to the historic Suchindram Thanumalayaswamy Temple, the wetland connects cultural heritage with ecological conservation."},{title:"Acacia Roosting Islands",icon:"🌳",fact:"Submerged Acacia tree mounds planted inside the reservoir provide predator-safe roosting and breeding platforms for Spot-billed Pelicans and Painted Storks."},{title:"Dual Monsoon Beneficiary",icon:"🌧️",fact:"Positioned near India's southern tip, Suchindram receives rainfall from both the South-West Monsoon (June-Sept) and North-East Monsoon (Oct-Dec)."},{title:"Global Ramsar Honor",icon:"💧",fact:"Designated as Ramsar Site No. 2484 in August 2022, securing international recognition for Kanyakumari's freshwater tank ecosystem."}],BIRD_SPECIES=[{id:"spot-billed-pelican",name:"Spot-billed Pelican",scientificName:"Pelecanus philippensis",category:"wading-birds",status:"Near Threatened",season:"October to April (Breeding Resident)",diet:"Freshwater fish",wingspan:"140–150 cm",icon:"🦩",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Spot-billed_Pelican_Pelecanus_philippensis.jpg/800px-Spot-billed_Pelican_Pelecanus_philippensis.jpg",description:"Large greyish-white pelican with spotted upper pouch. Nests in tree colonies atop submerged Acacia islands in Suchindram tank."},{id:"bronze-winged-jacana",name:"Bronze-winged Jacana",scientificName:"Metopidius indicus",category:"wading-birds",status:"Least Concern",season:"Year-round Resident",diet:"Aquatic insects, seeds, mollusks",wingspan:"50–55 cm",icon:"🪶",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Bronze-winged_Jacana_%28Metopidius_indicus%29.jpg/800px-Bronze-winged_Jacana_%28Metopidius_indicus%29.jpg",description:"Dark-bodied waterbird with elongated toes that allow it to walk effortlessly across floating lotus lily pads."},{id:"painted-stork",name:"Painted Stork",scientificName:"Mycteria leucocephala",category:"wading-birds",status:"Near Threatened",season:"November to March (Breeding)",diet:"Small fish, frogs",wingspan:"150–160 cm",icon:"🪶",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Painted_Stork_Mycteria_leucocephala.jpg/800px-Painted_Stork_Mycteria_leucocephala.jpg",description:"Large stork with distinctive pink tertial wing feathers and yellow down-curved bill. Breeds in treetop colonies."},{id:"northern-pintail",name:"Northern Pintail",scientificName:"Anas acuta",category:"waterfowl",status:"Least Concern",season:"November to March (Migratory)",diet:"Seeds, aquatic plants, invertebrates",wingspan:"80–95 cm",icon:"🦆",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Northern_Pintail_Anas_acuta.jpg/800px-Northern_Pintail_Anas_acuta.jpg",description:"Slender migratory duck with pointed tail feathers. Flocks gather in Suchindram's open waters after long journeys from northern Eurasia."},{id:"glossy-ibis",name:"Glossy Ibis",scientificName:"Plegadis falcinellus",category:"wading-birds",status:"Least Concern",season:"October to March",diet:"Aquatic insects, crustaceans, small fish",wingspan:"80–95 cm",icon:"🪶",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Plegadis_falcinellus_-_Glossy_Ibis.jpg/800px-Plegadis_falcinellus_-_Glossy_Ibis.jpg",description:"Dark reddish-brown wading bird with iridescent metallic sheen and curved bill, probing shallow muddy edges."},{id:"garganey",name:"Garganey",scientificName:"Spatula querquedula",category:"waterfowl",status:"Least Concern",season:"November to March (Migratory)",diet:"Seeds, small aquatic organisms",wingspan:"58–69 cm",icon:"🦆",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Garganey_Spatula_querquedula.jpg/800px-Garganey_Spatula_querquedula.jpg",description:"Small migratory duck with distinctive white eye stripe in breeding males. Skitters rapidly across lily-covered waters."}],MAP_HOTSPOTS=[{id:"temple-entrance",title:"Suchindram Temple View Entrance",category:"visitor-facilities",lat:8.152,lng:77.464,type:"Main Entrance",description:"Northern access point with views of the historic Thanumalayaswamy temple tower across the open water tank."},{id:"central-watchtower",title:"Central Bird Observatory Watchtower",category:"viewpoints",lat:8.1505,lng:77.466,type:"Observation Tower",description:"Elevated tower equipped with viewing scopes overlooking central roosting trees and lotus beds."},{id:"theroor-channel",title:"Theroor Feeder Channel & Roosting Tree Islets",category:"ecological-zones",lat:8.1485,lng:77.4675,type:"Breeding Nursery",description:"Submerged Acacia tree mounds where Spot-billed Pelicans, Storks, and Herons nest."},{id:"southern-mudflats",title:"Southern Mudflats & Lily Beds",category:"ecological-zones",lat:8.147,lng:77.465,type:"Jacana Foraging Zone",description:"Shallow water zone covered in lotus pads, prime habitat for Bronze-winged and Pheasant-tailed Jacanas."},{id:"bund-eco-trail",title:"Perimeter Tank Bund Eco-Trail",category:"trails",lat:8.151,lng:77.467,type:"Walking Track",description:"2.1 km shaded walking trail along the earthen dam, offering excellent morning photography spots."}],GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Spot-billed_Pelican_Pelecanus_philippensis.jpg/800px-Spot-billed_Pelican_Pelecanus_philippensis.jpg",caption:"Spot-billed Pelican perched on Acacia branches in Suchindram tank",category:"Avian Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Bronze-winged_Jacana_%28Metopidius_indicus%29.jpg/800px-Bronze-winged_Jacana_%28Metopidius_indicus%29.jpg",caption:"Bronze-winged Jacana stepping across floating water lily leaves",category:"Avian Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Painted_Stork_Mycteria_leucocephala.jpg/800px-Painted_Stork_Mycteria_leucocephala.jpg",caption:"Painted Stork standing near shallow waters during nesting season",category:"Avian Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Northern_Pintail_Anas_acuta.jpg/800px-Northern_Pintail_Anas_acuta.jpg",caption:"Northern Pintail flock swimming near the central watchtower",category:"Avian Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Plegadis_falcinellus_-_Glossy_Ibis.jpg/800px-Plegadis_falcinellus_-_Glossy_Ibis.jpg",caption:"Glossy Ibis probing soft wetland silt along the tank edge",category:"Avian Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Garganey_Spatula_querquedula.jpg/800px-Garganey_Spatula_querquedula.jpg",caption:"Garganey dabbling gracefully in shallow Lotus pads",category:"Avian Wildlife"}];"undefined"!=typeof module&&module.exports&&(module.exports={SUCHINDRAM_INFO:SUCHINDRAM_INFO,SUCHINDRAM_SECTIONS:SUCHINDRAM_SECTIONS,INTERESTING_FACTS:INTERESTING_FACTS,BIRD_SPECIES:BIRD_SPECIES,MAP_HOTSPOTS:MAP_HOTSPOTS,GALLERY_IMAGES:GALLERY_IMAGES});